package app.kivo.store;
import android.util.JsonReader;import android.util.JsonToken;import android.os.Build;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;
/** Independent official F-Droid connector. The compact snapshot is covered by Kivo's APK signature. */
final class Fdroid {
 final MainActivity host;volatile Map<String,JSONObject> entries=Collections.emptyMap();volatile boolean syncing;
 Fdroid(MainActivity h){host=h;}
 void load()throws Exception{try(InputStream meta=host.getAssets().open("fdroid-snapshot.json")){long stamp=new JSONObject(MainActivity.read(meta,10000)).getLong("timestamp");if(host.prefs.getLong("fdroidTimestamp",0)<stamp)host.prefs.edit().putLong("fdroidTimestamp",stamp).apply();}File f=new File(host.getFilesDir(),"fdroid-catalog.json");try(InputStream in=f.isFile()?new FileInputStream(f):host.getAssets().open("fdroid-catalog.json")){apply(new JSONArray(MainActivity.read(in,24*1024*1024)));}catch(Exception e){try(InputStream in=host.getAssets().open("fdroid-catalog.json")){apply(new JSONArray(MainActivity.read(in,24*1024*1024)));}}}
 void apply(JSONArray data)throws Exception{Map<String,JSONObject> next=new HashMap<>();for(int i=0;i<data.length();i++){JSONObject a=data.getJSONObject(i);next.put(a.getString("repo"),a);}entries=Collections.unmodifiableMap(next);host.send("fdroid",data);state("ready","");host.installedApps.requestScan();}
 void state(String s,String message){JSONObject o=new JSONObject();try{o.put("id","fdroid");o.put("state",s);o.put("count",entries.size());o.put("message",message);o.put("updated",host.prefs.getLong("fdroidTimestamp",0));}catch(Exception ignored){}host.send("sourceState",o);}
 JSONObject find(String raw)throws Exception{JSONObject a=entries.get(MainActivity.repo(raw));if(a==null)throw new IOException("La app ya no está en el índice F-Droid.");return a;}
 void sync(){if(syncing)return;syncing=true;host.transfers.execute(()->{File jar=null,index=null,temp=null;try{state("syncing","Descargando y verificando el índice oficial…");jar=File.createTempFile("fdroid-entry-",".jar",host.getCacheDir());fetch("/entry.jar",jar,1024*1024,null,-1);JSONObject entry=new JSONObject(new String(RepoTrust.entry(jar),"UTF-8"));long stamp=entry.getLong("timestamp");if(stamp<host.prefs.getLong("fdroidTimestamp",0))throw new SecurityException("Se rechazó un índice anterior al guardado.");JSONObject ref=entry.getJSONObject("index");index=File.createTempFile("fdroid-index-",".json",host.getCacheDir());fetch(ref.getString("name"),index,100*1024*1024,ref.getString("sha256"),ref.getLong("size"));JSONArray compact=compact(index);if(compact.length()==0)throw new IOException("Índice sin aplicaciones compatibles.");temp=new File(host.getFilesDir(),"fdroid-catalog.tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(compact.toString().getBytes("UTF-8"));out.getFD().sync();}File target=new File(host.getFilesDir(),"fdroid-catalog.json");if(!temp.renameTo(target))throw new IOException("No se pudo guardar el índice.");host.prefs.edit().putLong("fdroidTimestamp",stamp).apply();apply(compact);host.status("F-Droid actualizado: "+compact.length()+" aplicaciones.");}catch(Exception e){state("error","No se pudo actualizar F-Droid. Puedes reintentar; el catálogo guardado sigue disponible.");host.status("F-Droid: "+e.getMessage());}finally{if(jar!=null)jar.delete();if(index!=null)index.delete();if(temp!=null)temp.delete();syncing=false;}});}
 static boolean safePath(String path){return path.startsWith("/")&&!path.contains("..")&&!path.contains(":")&&!path.contains("?")&&!path.contains("#")&&!path.contains("\\");}
 static void fetch(String path,File target,int max,String hash,long size)throws Exception{if(!safePath(path))throw new IOException("Ruta F-Droid no válida.");HttpURLConnection c=(HttpURLConnection)new URL("https://f-droid.org/repo"+path).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(false);try{if(c.getResponseCode()!=200)throw new IOException("F-Droid respondió "+c.getResponseCode());MessageDigest md=MessageDigest.getInstance("SHA-256");long total=0;try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(target)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){total+=n;if(total>max)throw new IOException("Índice demasiado grande.");out.write(b,0,n);md.update(b,0,n);}}if(size>=0&&total!=size)throw new IOException("Índice incompleto.");if(hash!=null&&(!hash.matches("[a-f0-9]{64}")||!RepoTrust.hex(md.digest()).equals(hash)))throw new SecurityException("La huella del índice no coincide.");}finally{c.disconnect();}}
 JSONArray compact(File index)throws Exception{JSONArray out=new JSONArray();try(JsonReader r=new JsonReader(new InputStreamReader(new FileInputStream(index),"UTF-8"))){r.beginObject();while(r.hasNext()){if(!r.nextName().equals("packages")){r.skipValue();continue;}r.beginObject();while(r.hasNext()){String pkg=r.nextName();JSONObject raw=object(r);JSONObject a=normalize(pkg,raw,Build.VERSION.SDK_INT,Arrays.asList(Build.SUPPORTED_ABIS));if(a!=null)out.put(a);}r.endObject();}r.endObject();}return out;}
 static JSONObject object(JsonReader r)throws Exception{JSONObject out=new JSONObject();r.beginObject();while(r.hasNext()){String k=r.nextName();out.put(k,value(r));}r.endObject();return out;}
 static Object value(JsonReader r)throws Exception{JsonToken t=r.peek();if(t==JsonToken.BEGIN_OBJECT)return object(r);if(t==JsonToken.BEGIN_ARRAY){JSONArray a=new JSONArray();r.beginArray();while(r.hasNext())a.put(value(r));r.endArray();return a;}if(t==JsonToken.NULL){r.nextNull();return JSONObject.NULL;}if(t==JsonToken.BOOLEAN)return r.nextBoolean();if(t==JsonToken.NUMBER){String n=r.nextString();try{return Long.parseLong(n);}catch(Exception e){return Double.parseDouble(n);}}return r.nextString();}
 static String localized(JSONObject m,String key){Object v=m.opt(key);if(v instanceof JSONObject){JSONObject o=(JSONObject)v;for(String l:new String[]{"es","es-ES","en-US","en-GB"})if(o.has(l))return o.optString(l);Iterator<String> ks=o.keys();return ks.hasNext()?o.optString(ks.next()):"";}return v instanceof String?(String)v:"";}
 static JSONObject localizedObject(JSONObject o){if(o==null)return null;for(String l:new String[]{"es","es-ES","en-US","en-GB"})if(o.optJSONObject(l)!=null)return o.optJSONObject(l);Iterator<String> ks=o.keys();return ks.hasNext()?o.optJSONObject(ks.next()):null;}
 static JSONObject normalize(String pkg,JSONObject raw,int sdk,List<String> abis)throws Exception{return normalize(pkg,raw,sdk,abis,"fdroid","https://f-droid.org/repo");}
 static JSONObject normalize(String pkg,JSONObject raw,int sdk,List<String> abis,String source,String base)throws Exception{
  if(!pkg.matches("[A-Za-z0-9_]+(?:\\.[A-Za-z0-9_]+)+"))return null;JSONObject m=raw.optJSONObject("metadata"),vs=raw.optJSONObject("versions");if(m==null||vs==null)return null;
  List<JSONObject> versions=new ArrayList<>();Iterator<String> keys=vs.keys();while(keys.hasNext()){JSONObject v=vs.optJSONObject(keys.next());if(v==null)continue;JSONObject man=v.optJSONObject("manifest"),file=v.optJSONObject("file");if(man==null||file==null||!file.optString("name").endsWith(".apk")||!safePath(file.optString("name"))||!file.optString("sha256").matches("[a-f0-9]{64}")||file.optLong("size")<1||file.optLong("size")>500L*1024*1024)continue;if(v.optJSONArray("releaseChannels")!=null&&v.optJSONArray("releaseChannels").length()>0)continue;JSONObject use=man.optJSONObject("usesSdk");if(use!=null&&(use.optInt("minSdkVersion",1)>sdk||(use.has("maxSdkVersion")&&use.optInt("maxSdkVersion")<sdk)))continue;JSONArray nativecode=man.optJSONArray("nativecode");boolean ok=nativecode==null||nativecode.length()==0;if(nativecode!=null)for(int i=0;i<nativecode.length();i++)if(abis.contains(nativecode.optString(i)))ok=true;if(!ok)continue;JSONArray sign=man.optJSONObject("signer")==null?null:man.optJSONObject("signer").optJSONArray("sha256");if(sign==null||sign.length()==0)continue;String preferred=m.optString("preferredSigner");if(!preferred.isEmpty()&&!sign.toString().contains(preferred))continue;versions.add(v);}
  if(versions.isEmpty())return null;Collections.sort(versions,(a,b)->Long.compare(b.optJSONObject("manifest").optLong("versionCode"),a.optJSONObject("manifest").optLong("versionCode")));JSONObject best=versions.get(0),man=best.getJSONObject("manifest");JSONArray assets=new JSONArray();for(int i=0;i<Math.min(4,versions.size());i++){JSONObject v=versions.get(i),f=v.getJSONObject("file"),vm=v.getJSONObject("manifest");if(vm.optLong("versionCode")!=man.optLong("versionCode"))continue;assets.put(new JSONObject().put("id",vm.optLong("versionCode")).put("name",f.getString("name").substring(1)).put("url",base+f.getString("name")).put("size",f.getLong("size")).put("digest","sha256:"+f.getString("sha256")).put("signers",vm.getJSONObject("signer").getJSONArray("sha256")).put("package",pkg));}
  JSONObject a=new JSONObject();a.put("repo",source+"/"+pkg);a.put("package",pkg);if(m.optLong("added")>0)a.put("addedAt",new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date(m.optLong("added"))));a.put("source",source);a.put("name",localized(m,"name"));if(a.optString("name").isEmpty())a.put("name",pkg);a.put("description",localized(m,"summary"));a.put("longDescription",android.text.Html.fromHtml(localized(m,"description"),android.text.Html.FROM_HTML_MODE_LEGACY).toString());a.put("version",man.optString("versionName"));a.put("versionCode",man.optLong("versionCode"));a.put("date",new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date(best.optLong("added"))));a.put("available",true);a.put("indexed",false);a.put("assets",assets);a.put("topics",m.optJSONArray("categories"));a.put("license",m.optString("license"));a.put("publisher",m.optString("authorName","F-Droid"));a.put("referenceMinSdk",man.optJSONObject("usesSdk")==null?1:man.optJSONObject("usesSdk").optInt("minSdkVersion",1));a.put("referenceVersion",man.optString("versionName"));a.put("website",m.optString("webSite"));a.put("sourceCode",m.optString("sourceCode"));a.put("antiFeatures",best.optJSONObject("antiFeatures"));JSONObject icon=localizedObject(m.optJSONObject("icon"));if(icon!=null){a.put("iconPath",icon.optString("name"));a.put("iconHash",icon.optString("sha256"));}JSONArray shots=new JSONArray();JSONObject phone=m.optJSONObject("screenshots")==null?null:m.optJSONObject("screenshots").optJSONObject("phone");if(phone!=null){JSONArray chosen=null;for(String l:new String[]{"es","es-ES","en-US"})if(phone.optJSONArray(l)!=null){chosen=phone.optJSONArray(l);break;}if(chosen==null){Iterator<String> ls=phone.keys();if(ls.hasNext())chosen=phone.optJSONArray(ls.next());}if(chosen!=null)for(int i=0;i<Math.min(4,chosen.length());i++){JSONObject shot=chosen.getJSONObject(i);shots.put(new JSONObject().put("path",shot.optString("name")).put("sha256",shot.optString("sha256")));}}a.put("screenshots",shots);return a;
 }
}
